export function getTrackBySlug(slug: string): MusicTrackDef | undefined {
  return MUSIC_TRACK_CATALOG.find((t) => t.slug === slug);
}

export function listTracksByVibe(vibe: MusicTrackDef["vibe"]): MusicTrackDef[] {
  return MUSIC_TRACK_CATALOG.filter((t) => t.vibe === vibe);
}
